  const g = newLot();
  // carport bay: the ground is the floor, the screen closes its south side at z=21
  room(g, [1, 7, 9, 20], { floorY: 0, ceiling: false, open: (x, y, z) => z === 21 && y >= 1 && y <= 3 });
  const r = h1.breeze_screen(g, 1, 9, 1, 4, 21);
